// Global site search (Fleet 1.0, 2026-10-31).
//
// Client-side over a build-time static index (/search-index.json,
// generated by scripts/generate-search-index.py from the site's own
// data files). Bounded by construction: the index is a fixed file
// (one entry per page/solution/package/MCP server — on the order of
// a hundred entries), it is fetched at most once per page and only
// after the visitor first interacts with the search box, matching is
// a single linear scan capped at 8 rendered results, and there are
// no timers or retries. Selecting a result navigates to its URL.
(function () {
  "use strict";
  var MAX_RESULTS = 8;
  var index = null;
  var loading = false;
  function init() {
    var input = document.getElementById("site-search-input");
    var list = document.getElementById("site-search-results");
    if (!input || !list) return;
    var active = -1;
    var items = [];
    function ensureIndex(cb) {
      if (index) { cb(); return; }
      if (loading) return;
      loading = true;
      fetch("/search-index.json")
        .then(function (r) { return r.ok ? r.json() : []; })
        .then(function (data) { index = Array.isArray(data) ? data : []; loading = false; cb(); })
        .catch(function () { index = []; loading = false; });
    }
    function close() {
      list.hidden = true;
      list.innerHTML = "";
      items = [];
      active = -1;
      input.setAttribute("aria-expanded", "false");
    }
    function render(results) {
      list.innerHTML = "";
      items = results;
      active = results.length ? 0 : -1;
      results.forEach(function (entry, i) {
        var li = document.createElement("li");
        li.setAttribute("role", "option");
        li.id = "site-search-result-" + i;
        if (i === active) li.classList.add("is-active");
        var a = document.createElement("a");
        a.href = entry.url;
        var title = document.createElement("span");
        title.className = "search-result-title";
        title.textContent = entry.title;
        var kind = document.createElement("span");
        kind.className = "search-result-kind";
        kind.textContent = entry.kind;
        var summary = document.createElement("span");
        summary.className = "search-result-summary";
        summary.textContent = entry.summary || "";
        a.appendChild(title);
        a.appendChild(kind);
        a.appendChild(summary);
        li.appendChild(a);
        li.addEventListener("mouseenter", function () { setActive(i); });
        list.appendChild(li);
      });
      list.hidden = results.length === 0;
      input.setAttribute("aria-expanded", results.length ? "true" : "false");
      if (results.length) input.setAttribute("aria-activedescendant", "site-search-result-0");
    }
    function setActive(i) {
      active = i;
      Array.prototype.forEach.call(list.children, function (li, j) {
        li.classList.toggle("is-active", j === active);
      });
      input.setAttribute("aria-activedescendant", "site-search-result-" + active);
    }
    function search() {
      var q = input.value.trim().toLowerCase();
      if (q.length < 2) { close(); return; }
      ensureIndex(function () {
        var terms = q.split(/\s+/);
        var hits = [];
        for (var i = 0; i < index.length && hits.length < MAX_RESULTS * 4; i++) {
          var entry = index[i];
          var hay = (entry.title + " " + entry.kind + " " + (entry.summary || "")).toLowerCase();
          var ok = terms.every(function (term) { return hay.indexOf(term) !== -1; });
          if (ok) hits.push(entry);
        }
        render(hits.slice(0, MAX_RESULTS));
      });
    }
    input.addEventListener("input", search);
    input.addEventListener("focus", search);
    input.addEventListener("keydown", function (event) {
      if (!items.length) return;
      if (event.key === "ArrowDown") { setActive(Math.min(items.length - 1, active + 1)); event.preventDefault(); }
      else if (event.key === "ArrowUp") { setActive(Math.max(0, active - 1)); event.preventDefault(); }
      else if (event.key === "Enter" && active >= 0) {
        window.location.href = items[active].url;
        event.preventDefault();
      } else if (event.key === "Escape") { close(); }
    });
    document.addEventListener("click", function (event) {
      if (!list.contains(event.target) && event.target !== input) close();
    });
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
